class VectorMemory:
    def __init__(self):
        self.index = None
        self.pinecone_client = None
        try:
            import pinecone
            from pinecone import Pinecone, ServerlessSpec
            self.pinecone_client = Pinecone(api_key=os.getenv('PINECONE_API_KEY'))
            try:
                self.index = self.pinecone_client.Index('cognitive-memory')
                logger.info("Pinecone vector memory initialized successfully")
            except Exception as e:
                logger.warning(f"Pinecone index not found, attempting to create: {e}")
                pinecone_region = os.getenv('PINECONE_REGION', 'us-east-1')
                self.pinecone_client.create_index(
                    name='cognitive-memory',
                    dimension=1536,
                    metric='cosine',
                    spec=ServerlessSpec(cloud='aws', region=pinecone_region)
                )
                time.sleep(60)
                self.index = self.pinecone_client.Index('cognitive-memory')
                logger.info("Pinecone index created successfully")
        except Exception as e:
            logger.warning(f"Pinecone initialization failed: {e} - Vector memory disabled")

    def _get_openai_embedding(self, text: str) -> List[float]:
        try:
            from openai import OpenAI
            client = OpenAI(api_key=os.getenv('OPENAI_API_KEY'))
            response = client.embeddings.create(
                model="text-embedding-3-small",
                input=text
            )
            return response.data[0].embedding
        except Exception as e:
            logger.error(f"OpenAI embedding failed: {e}")
            return [0.0] * 1536

    def store_insight(self, content: str, metadata: Dict):
        if not self.index:
            logger.debug("Vector memory not available - skipping insight storage")
            return None
        try:
            vector_id = hashlib.sha256(f"{content}{time.time()}".encode()).hexdigest()
            embedding = self._get_openai_embedding(content)
            self.index.upsert(vectors=[{
                'id': vector_id,
                'values': embedding,
                'metadata': {
                    **metadata,
                    'content': content[:1000],
                    'timestamp': time.time()
                }
            }])
            return vector_id
        except Exception as e:
            logger.error(f"Failed to store insight: {e}")
            return None

    def recall_similar(self, query: str, top_k: int = 20) -> List[Dict]:
        if not self.index:
            logger.debug("Vector memory not available - returning empty memories")
            return []
        try:
            query_embedding = self._get_openai_embedding(query)
            results = self.index.query(vector=query_embedding, top_k=top_k, include_metadata=True)
            recalled = []
            for match in results.matches:
                recalled.append({
                    'content': match.metadata.get('content', ''),
                    'score': match.score,
                    'metadata': match.metadata
                })
            return recalled
        except Exception as e:
            logger.error(f"Pinecone recall_similar failed: {e}")
            return []

