    def create_research_plan(self, query: str, context: List[Dict]) -> Dict:
        context_text = "\n".join([f"- {item['content'][:500]}" for item in context[:10]])
        planning_prompt = f"""You are a strategic research planner. Create a comprehensive, adaptive research plan.

Query: {query}

Previous knowledge from memory:

{context_text}

Create a detailed research plan with:

1. Primary research objectives (3-5 specific goals)
